<script lang="ts">import{gameCommands,gameState}from'$lib/application/game-store';import{FRUIT_TREES,type FruitTreeId}from'$lib/content/advanced-farm';import{FISH}from'$lib/content/fish';export let close:()=>void;const trees=Object.entries(FRUIT_TREES) as Array<[FruitTreeId,(typeof FRUIT_TREES)[FruitTreeId]]>;</script>
<div class="modal" role="dialog" aria-modal="true"><section><button class="close" on:click={close}>×</button><small>PERTANIAN LANJUTAN</small><h2>Orchard, Lebah & Kolam</h2><h3>KEBUN BUAH</h3><div class="cards">{#each trees as [id,tree]}<article><b>{tree.name}</b><span>{tree.growDays} hari · {tree.seasons.join(', ')}</span><button on:click={()=>gameCommands.buySapling(id)}>Beli bibit {tree.price}</button><button on:click={()=>gameCommands.plantTree(id)}>Tanam</button></article>{/each}</div><div class="list">{#each $gameState.orchard as tree}<button on:click={()=>gameCommands.harvestTree(tree.id)}>{FRUIT_TREES[tree.type].name} · umur {$gameState.day-tree.plantedDay} hari · Panen</button>{/each}</div>
<h3>PETERNAKAN LEBAH</h3><p>{$gameState.apiary.hives} sarang · {$gameState.apiary.honeyReady} madu siap · dipengaruhi bunga dan musim</p><button on:click={()=>gameCommands.buyHive()}>Tambah Sarang</button><button on:click={()=>gameCommands.collectHoney()}>Panen Madu</button>
<h3>KOLAM IKAN</h3>{#if !$gameState.fishPond.built}<button on:click={()=>gameCommands.buildPond()}>Bangun · 4 bambu + 2 batu</button>{:else}<p>Lv.{$gameState.fishPond.level} · kondisi {$gameState.fishPond.condition}% · stok {$gameState.fishPond.stock}</p><div class="cards">{#each Object.values(FISH).filter(fish=>$gameState.inventory[`fish_${fish.id}`]>0) as fish}<button on:click={()=>gameCommands.stockPond(fish.id)}>Tebar {fish.name}</button>{/each}</div><button on:click={()=>gameCommands.feedPond()}>Beri Pakan</button><button on:click={()=>gameCommands.harvestPond()}>Panen Ikan</button>{/if}</section></div>
<style>.modal{position:fixed;z-index:20;inset:0;background:#071a16dd;display:grid;place-items:center;padding:15px}section{position:relative;width:min(800px,100%);max-height:92vh;overflow:auto;padding:25px;background:#e8ddb8;color:#203c35;border:8px double #6e5037}.close{position:absolute;right:8px;top:6px;border:0;background:none;font-size:1.6rem}h2{font:900 2rem Georgia}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.cards article{display:grid;gap:5px;padding:10px;background:#fff7d9;border:2px solid #927340}.cards span{font-size:.66rem}button{padding:7px;background:#315d4b;color:white;border:0;margin:3px}.list{display:grid;margin-top:8px}@media(max-width:600px){.cards{grid-template-columns:1fr 1fr}}</style>
